INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Ressourcennutzung nur bei großen Systemen wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Systeme profitieren"}, {"text": "Ja", "correct": false, "because": "Effizienz immer relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich bei der Verbesserung der Ressourcennutzung?', 3, '[{"text": "Effizienz steigern", "correct": true, "because": "Weniger Speicher und CPU"}, {"text": "Code kürzer machen", "correct": false, "because": "Nicht primär"}, {"text": "UI verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen verbessern die Ressourcennutzung?', 5, '[{"text": "Speicherlecks vermeiden", "correct": true, "because": "Reduziert Speicherverbrauch"}, {"text": "Effiziente Algorithmen", "correct": true, "because": "Senkt CPU-Last"}, {"text": "Mehr Threads", "correct": false, "because": "Kann Last erhöhen"}, {"text": "Höhere Auflösung", "correct": false, "because": "UI-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ressourcennutzung optimiert Laufzeit. b) Sie erhöht immer die Sicherheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Ressourcennutzung?', 4, '[{"text": "Speicherverbrauch", "correct": false, "because": "Kern der Optimierung"}, {"text": "CPU-Auslastung", "correct": false, "because": "Muss berücksichtigt werden"}, {"text": "Farbschema", "correct": true, "because": "Kein Ressourcenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ressourcennutzung ohne Profiling geht?', 2, '[{"text": "Nein", "correct": true, "because": "Profiling zeigt Schwachstellen"}, {"text": "Ja", "correct": false, "because": "Ohne Analyse schwierig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Ressourcennutzung?', 3, '[{"text": "Profiler", "correct": true, "because": "Misst Speicher und CPU"}, {"text": "Debugger", "correct": false, "because": "Fehlerfokussiert"}, {"text": "Compiler", "correct": false, "because": "Nur Übersetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Ressourcennutzung?', 5, '[{"text": "Algorithmeneffizienz", "correct": true, "because": "Senkt CPU-Bedarf"}, {"text": "Speichermanagement", "correct": true, "because": "Verhindert Leaks"}, {"text": "UI-Animationen", "correct": false, "because": "Sekundär"}, {"text": "Farbtiefe", "correct": false, "because": "Minimaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ressourcennutzung spart Kosten. b) Sie macht Code immer schneller. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Ressourcennutzung?', 4, '[{"text": "Profiling-Tools", "correct": false, "because": "Analyse essenziell"}, {"text": "Effiziente Datenstrukturen", "correct": false, "because": "Optimiert Speicher"}, {"text": "Hübsche UI", "correct": true, "because": "Kein Ressourcenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Ressourcennutzung ohne Tests möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Tests zeigen Optimierungspotenzial"}, {"text": "Ja", "correct": false, "because": "Blindschüsse ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken verbessern die Ressourcennutzung?', 4, '[{"text": "Lazy Loading", "correct": true, "because": "Reduziert Speicherbedarf"}, {"text": "Caching", "correct": true, "because": "Spart CPU-Zyklen"}, {"text": "Hohe Auflösung", "correct": false, "because": "Erhöht Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Ressourcennutzung nur Hardware betrifft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Software beeinflusst stark"}, {"text": "Ja", "correct": false, "because": "Code ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Ressourcennutzung?', 3, '[{"text": "Effiziente Algorithmen", "correct": true, "because": "Senkt CPU-Last"}, {"text": "Schnelle Deployment", "correct": false, "because": "Nicht primär"}, {"text": "Viele Features", "correct": false, "because": "Kann Last erhöhen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ressourcennutzung reduziert Speicherbedarf. b) Sie ersetzt Hardware-Upgrades.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Upgrades oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme löst Ressourcennutzung?', 5, '[{"text": "Hoher Speicherverbrauch", "correct": true, "because": "Optimiert Speicher"}, {"text": "CPU-Überlastung", "correct": true, "because": "Effizientere Prozesse"}, {"text": "Schlechte UI", "correct": false, "because": "Anderer Bereich"}, {"text": "Fehlende Features", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Ressourcennutzung unwichtig?', 3, '[{"text": "Speichermanagement", "correct": false, "because": "Kern der Optimierung"}, {"text": "Algorithmeneffizienz", "correct": false, "because": "Reduziert CPU"}, {"text": "Farbanimationen", "correct": true, "because": "Kein Ressourcenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Ressourcennutzung die Komplexität?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Effizienz"}, {"text": "Ja", "correct": false, "because": "Kann vereinfachen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ressourcennutzung Tests ersetzt?', 2, '[{"text": "Nein", "correct": true, "because": "Tests ergänzen Optimierung"}, {"text": "Ja", "correct": false, "because": "Tests bleiben nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft bei der Ressourcennutzung?', 4, '[{"text": "Garbage Collection", "correct": true, "because": "Freigabe ungenutzter Speicher"}, {"text": "Mehr Threads", "correct": false, "because": "Kann Last erhöhen"}, {"text": "Höhere Taktfrequenz", "correct": false, "because": "Hardwareabhängig"}]');
